export const SH1106_PY = "#\n# MicroPython SH1106 OLED driver, I2C and SPI interfaces\n#\n# The MIT License (MIT)\n#\n# Copyright (c) 2016 Radomir Dopieralski (@deshipu),\n#               2017-2021 Robert Hammelrath (@robert-hh)\n#               2021 Tim Weber (@scy)\n#\n# Permission is hereby granted, free of charge, to any person obtaining a copy\n# of this software and associated documentation files (the \"Software\"), to deal\n# in the Software without restriction, including without limitation the rights\n# to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n# copies of the Software, and to permit persons to whom the Software is\n# furnished to do so, subject to the following conditions:\n#\n# The above copyright notice and this permission notice shall be included in\n# all copies or substantial portions of the Software.\n#\n# THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n# IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n# FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n# AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n# LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n# OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN\n# THE SOFTWARE.\n#\n# Sample code sections for ESP8266 pin assignments\n# ------------ SPI ------------------\n# Pin Map SPI\n#   - 3v - xxxxxx   - Vcc\n#   - G  - xxxxxx   - Gnd\n#   - D7 - GPIO 13  - Din / MOSI fixed\n#   - D5 - GPIO 14  - Clk / Sck fixed\n#   - D8 - GPIO 4   - CS (optional, if the only connected device)\n#   - D2 - GPIO 5   - D/C\n#   - D1 - GPIO 2   - Res\n#\n# for CS, D/C and Res other ports may be chosen.\n#\n# from machine import Pin, SPI\n# import sh1106\n\n# spi = SPI(1, baudrate=1000000)\n# display = sh1106.SH1106_SPI(128, 64, spi, Pin(5), Pin(2), Pin(4))\n# display.sleep(False)\n# display.fill(0)\n# display.text('Testing 1', 0, 0, 1)\n# display.show()\n#\n# --------------- I2C ------------------\n#\n# Pin Map I2C\n#   - 3v - xxxxxx   - Vcc\n#   - G  - xxxxxx   - Gnd\n#   - D2 - GPIO 5   - SCK / SCL\n#   - D1 - GPIO 4   - DIN / SDA\n#   - D0 - GPIO 16  - Res\n#   - G  - xxxxxx     CS\n#   - G  - xxxxxx     D/C\n#\n# Pin's for I2C can be set almost arbitrary\n#\n# from machine import Pin, I2C\n# import sh1106\n#\n# i2c = I2C(scl=Pin(5), sda=Pin(4), freq=400000)\n# display = sh1106.SH1106_I2C(128, 64, i2c, Pin(16), 0x3c)\n# display.sleep(False)\n# display.fill(0)\n# display.text('Testing 1', 0, 0, 1)\n# display.show()\n\nfrom micropython import const\nimport utime as time\nimport framebuf\n\n\n# a few register definitions\n_SET_CONTRAST        = const(0x81)\n_SET_NORM_INV        = const(0xa6)\n_SET_DISP            = const(0xae)\n_SET_SCAN_DIR        = const(0xc0)\n_SET_SEG_REMAP       = const(0xa0)\n_LOW_COLUMN_ADDRESS  = const(0x00)\n_HIGH_COLUMN_ADDRESS = const(0x10)\n_SET_PAGE_ADDRESS    = const(0xB0)\n\n\nclass SH1106(framebuf.FrameBuffer):\n\n    def __init__(self, width, height, external_vcc, rotate=0):\n        self.width = width\n        self.height = height\n        self.external_vcc = external_vcc\n        self.flip_en = rotate == 180 or rotate == 270\n        self.rotate90 = rotate == 90 or rotate == 270\n        self.pages = self.height // 8\n        self.bufsize = self.pages * self.width\n        self.renderbuf = bytearray(self.bufsize)\n        self.pages_to_update = 0\n        self.delay = 0\n\n        if self.rotate90:\n            self.displaybuf = bytearray(self.bufsize)\n            # HMSB is required to keep the bit order in the render buffer\n            # compatible with byte-for-byte remapping to the display buffer,\n            # which is in VLSB. Else we'd have to copy bit-by-bit!\n            super().__init__(self.renderbuf, self.height, self.width,\n                             framebuf.MONO_HMSB)\n        else:\n            self.displaybuf = self.renderbuf\n            super().__init__(self.renderbuf, self.width, self.height,\n                             framebuf.MONO_VLSB)\n\n        # flip() was called rotate() once, provide backwards compatibility.\n        self.rotate = self.flip\n        self.init_display()\n\n    # abstractmethod\n    def write_cmd(self, *args, **kwargs): \n        raise NotImplementedError\n\n    # abstractmethod\n    def write_data(self,  *args, **kwargs):\n        raise NotImplementedError\n\n    def init_display(self):\n        self.reset()\n        self.fill(0)\n        self.show()\n        self.poweron()\n        # rotate90 requires a call to flip() for setting up.\n        self.flip(self.flip_en)\n\n    def poweroff(self):\n        self.write_cmd(_SET_DISP | 0x00)\n\n    def poweron(self):\n        self.write_cmd(_SET_DISP | 0x01)\n        if self.delay:\n            time.sleep_ms(self.delay)\n\n    def flip(self, flag=None, update=True):\n        if flag is None:\n            flag = not self.flip_en\n        mir_v = flag ^ self.rotate90\n        mir_h = flag\n        self.write_cmd(_SET_SEG_REMAP | (0x01 if mir_v else 0x00))\n        self.write_cmd(_SET_SCAN_DIR | (0x08 if mir_h else 0x00))\n        self.flip_en = flag\n        if update:\n            self.show(True) # full update\n\n    def sleep(self, value):\n        self.write_cmd(_SET_DISP | (not value))\n\n    def contrast(self, contrast):\n        self.write_cmd(_SET_CONTRAST)\n        self.write_cmd(contrast)\n\n    def invert(self, invert):\n        self.write_cmd(_SET_NORM_INV | (invert & 1))\n\n    def show(self, full_update = False):\n        # self.* lookups in loops take significant time (~4fps).\n        (w, p, db, rb) = (self.width, self.pages,\n                          self.displaybuf, self.renderbuf)\n        if self.rotate90:\n            for i in range(self.bufsize):\n                db[w * (i % p) + (i // p)] = rb[i]\n        if full_update:\n            pages_to_update = (1 << self.pages) - 1\n        else:\n            pages_to_update = self.pages_to_update\n        #print(\"Updating pages: {:08b}\".format(pages_to_update))\n        for page in range(self.pages):\n            if (pages_to_update & (1 << page)):\n                self.write_cmd(_SET_PAGE_ADDRESS | page)\n                self.write_cmd(_LOW_COLUMN_ADDRESS | 2)\n                self.write_cmd(_HIGH_COLUMN_ADDRESS | 0)\n                self.write_data(db[(w*page):(w*page+w)])\n        self.pages_to_update = 0\n\n    def pixel(self, x, y, color=None):\n        if color is None:\n            return super().pixel(x, y)\n        else:\n            super().pixel(x, y , color)\n            page = y // 8\n            self.pages_to_update |= 1 << page\n\n    def text(self, text, x, y, color=1):\n        super().text(text, x, y, color)\n        self.register_updates(y, y+7)\n\n    def line(self, x0, y0, x1, y1, color):\n        super().line(x0, y0, x1, y1, color)\n        self.register_updates(y0, y1)\n\n    def hline(self, x, y, w, color):\n        super().hline(x, y, w, color)\n        self.register_updates(y)\n\n    def vline(self, x, y, h, color):\n        super().vline(x, y, h, color)\n        self.register_updates(y, y+h-1)\n\n    def fill(self, color):\n        super().fill(color)\n        self.pages_to_update = (1 << self.pages) - 1\n\n    def blit(self, fbuf, x, y, key=-1, palette=None):\n        super().blit(fbuf, x, y, key, palette)\n        self.register_updates(y, y+self.height)\n\n    def scroll(self, x, y):\n        # my understanding is that scroll() does a full screen change\n        super().scroll(x, y)\n        self.pages_to_update =  (1 << self.pages) - 1\n\n    def fill_rect(self, x, y, w, h, color):\n        super().fill_rect(x, y, w, h, color)\n        self.register_updates(y, y+h-1)\n\n    def rect(self, x, y, w, h, color):\n        super().rect(x, y, w, h, color)\n        self.register_updates(y, y+h-1)\n\n    def ellipse(self, x, y, xr, yr, color):\n        super().ellipse(x, y, xr, yr, color)\n        self.register_updates(y-yr, y+yr-1)\n\n    def register_updates(self, y0, y1=None):\n        # this function takes the top and optional bottom address of the changes made\n        # and updates the pages_to_change list with any changed pages\n        # that are not yet on the list\n        start_page = max(0, y0 // 8)\n        end_page = max(0, y1 // 8) if y1 is not None else start_page\n        # rearrange start_page and end_page if coordinates were given from bottom to top\n        if start_page > end_page:\n            start_page, end_page = end_page, start_page\n        for page in range(start_page, end_page+1):\n            self.pages_to_update |= 1 << page\n\n    def reset(self, res=None):\n        if res is not None:\n            res(1)\n            time.sleep_ms(1)\n            res(0)\n            time.sleep_ms(20)\n            res(1)\n            time.sleep_ms(20)\n\n\nclass SH1106_I2C(SH1106):\n    def __init__(self, width, height, i2c, res=None, addr=0x3c,\n                 rotate=0, external_vcc=False, delay=0):\n        self.i2c = i2c\n        self.addr = addr\n        self.res = res\n        self.temp = bytearray(2)\n        self.delay = delay\n        if res is not None:\n            res.init(res.OUT, value=1)\n        super().__init__(width, height, external_vcc, rotate)\n\n    def write_cmd(self, cmd):\n        self.temp[0] = 0x80  # Co=1, D/C#=0\n        self.temp[1] = cmd\n        self.i2c.writeto(self.addr, self.temp)\n\n    def write_data(self, buf):\n        self.i2c.writeto(self.addr, b'\\x40'+buf)\n\n    def reset(self,res=None):\n        super().reset(self.res)\n\n\nclass SH1106_SPI(SH1106):\n    def __init__(self, width, height, spi, dc, res=None, cs=None,\n                 rotate=0, external_vcc=False, delay=0):\n        dc.init(dc.OUT, value=0)\n        if res is not None:\n            res.init(res.OUT, value=0)\n        if cs is not None:\n            cs.init(cs.OUT, value=1)\n        self.spi = spi\n        self.dc = dc\n        self.res = res\n        self.cs = cs\n        self.delay = delay\n        super().__init__(width, height, external_vcc, rotate)\n\n    def write_cmd(self, cmd):\n        if self.cs is not None:\n            self.cs(1)\n            self.dc(0)\n            self.cs(0)\n            self.spi.write(bytearray([cmd]))\n            self.cs(1)\n        else:\n            self.dc(0)\n            self.spi.write(bytearray([cmd]))\n\n    def write_data(self, buf):\n        if self.cs is not None:\n            self.cs(1)\n            self.dc(1)\n            self.cs(0)\n            self.spi.write(buf)\n            self.cs(1)\n        else:\n            self.dc(1)\n            self.spi.write(buf)\n\n    def reset(self, res=None):\n        super().reset(self.res)\n";
